// dual_agent_loop.mjs — the soulbis ⚔️ ⊥ soulbae 🧙 dual-agent harness engine.
//
//   (⚔️⊥⿻⊥🧙)😊 = neg ⊕ bnot → succ
//
// Target-agnostic. A concrete harness is a CONFIG (see SEAT_CONTRACT.md)
// passed to runHarness(config, rt). The two invariants the loop exists to
// keep: I(Y_S; Y_M | X) = 0 (the proposer never touches the held-out
// witnesses) and I(S; M | FP) < ε (the pair share only their root in the
// First Person). See TRUSTS.md.
//
// rt = { agent, parallel, pipeline, phase, log } — the Claude Code Workflow
// globals, or your own driver. The one import is the Gap tool (engine/gap.mjs):
// the hold-apart seed and draw are CODE, not a seat's shell arithmetic, so the
// same function the loop derives with is the one verify_run.mjs replays.
// tools/bundle.mjs inlines gap.mjs (and its kappa.mjs helpers) when it
// concatenates this file into a self-contained .workflow.mjs, because the
// Workflow runtime has no `import`.

// Code-derive the hold-apart seed and draw for a committed proposal (SALTED
// mode). Returns null in LEGACY mode (no saltSecret, or no declared gate.N),
// where the Gap seat still computes its own seed = sha256(proposal_canon) — so
// pre-existing instances and runs are unaffected.
//
// Salt is derived AFTER the proposal is committed, from a run-level secret the
// proposer never sees (D1, option A). Grinding the proposal cannot fix the
// draw. Census mode probes every fact; sample mode draws gate.count of N.
function deriveHoldApart(proposal, { gate, saltSecret, sourceHash }) {
  if (!saltSecret || !gate || !Number.isInteger(gate.N)) return null
  const canon = canonicalize(proposal)
  const hProposal = hashCanon(canon)
  const salt = perProposalSalt(saltSecret, hProposal)
  const seedHex = deriveSeed({ hSource: sourceHash || null, hProposal, salt })
  const N = gate.N
  const count = gate.count || gate.n || 8
  const mode = gate.mode || 'sample'
  const drawIndices = mode === 'census'
    ? Array.from({ length: N }, (_, k) => k + 1)
    : draw(seedHex, N, count)
  return { salted: true, mode, N, count, hSource: sourceHash || null, hProposal, salt, seedHex, drawIndices }
}

function bootPreamble(root, repo, seatCard) {
  return `You are a seat in a soulbis/soulbae dual-agent harness. Instance: ${repo}. Skeleton root: ${root}.
BOOT (mandatory, in order): read ${root}/GROUND_RULES.md, then ${root}/TRUSTS.md, then your seat card ${root}/seats/${seatCard}, then ${repo}/frontier.json. If any of these files is missing, STOP and return an error naming the missing path — do not proceed unbound (T3). GR-1..GR-10 and trusts T1..T6 bind you. Read nothing else shared between seats (T3). Your final message is consumed as data by the orchestrator, not shown to a human.`
}

function validateConfig(config) {
  const errs = []
  const need = (cond, msg) => { if (!cond) errs.push(msg) }
  need(config && typeof config.name === 'string' && config.name, 'config.name required')
  need(config?.door === 'first-person', "config.door must be the literal 'first-person' (T6: the door is the First Person's)")
  need(typeof config?.heldApartRule === 'string' && config.heldApartRule.trim().length > 0, 'config.heldApartRule required (T2/GR-4: the Gap is held apart)')
  need(config?.objective?.metric, 'config.objective.metric required (GR-1)')
  need(config?.objective?.gate, 'config.objective.gate required (T5: the multiplicative gate)')
  need(config?.objective?.hardConstraint, 'config.objective.hardConstraint required (GR-3)')
  need(Array.isArray(config?.keystoneOnlyWrites) && config.keystoneOnlyWrites.length > 0, 'config.keystoneOnlyWrites required (GR-10)')
  need(Array.isArray(config?.finders) && config.finders.length >= 2, 'config.finders needs >= 2 lenses (blind complements)')
  if (Array.isArray(config?.finders)) {
    const lenses = new Set(config.finders.map(f => f && f.lens))
    need(lenses.size === config.finders.length, 'config.finders lenses must be distinct')
  }
  for (const p of ['measure', 'propose', 'holdApart', 'assay', 'critic', 'chronicle']) {
    need(typeof config?.prompts?.[p] === 'function', `config.prompts.${p} required (T1: the promises must be seated)`)
  }
  for (const s of ['measure', 'proposal', 'gap', 'verdict', 'critic']) {
    need(config?.schemas?.[s] && typeof config.schemas[s] === 'object', `config.schemas.${s} required`)
  }
  need(typeof config?.isValidated === 'function', 'config.isValidated required')
  need(typeof config?.isStructural === 'function', 'config.isStructural required')
  need(Number.isFinite(config?.stop?.dryRounds) && config.stop.dryRounds >= 1, 'config.stop.dryRounds required')
  need(Number.isFinite(config?.stop?.maxRounds) && config.stop.maxRounds >= 1, 'config.stop.maxRounds required')
  return errs
}

async function runHarness(config, rt, runArgs = {}) {
  const { agent, parallel, pipeline, phase, log } = rt
  const errs = validateConfig(config)
  if (errs.length) throw new Error('config violates the seat contract:\n  - ' + errs.join('\n  - '))

  const repo = String(runArgs.repo || config.repo || '').replace(/\\/g, '/')
  if (!repo) throw new Error('runArgs.repo required (absolute path to the harness instance)')
  // root = where GROUND_RULES.md, TRUSTS.md, and seats/ live (the skeleton
  // clone). Defaults to the instance itself, which is only correct if the
  // instance carries its own copies (T3: every seat boots from the same docs).
  const root = String(runArgs.root || config.root || repo).replace(/\\/g, '/')
  const runId = String(runArgs.runId || 'r0')
  const runRoot = `${repo}/runs/${runId}`
  const BOOT = (card) => bootPreamble(root, repo, card)

  // ctx.args exposes the run's arguments to prompt builders, so a config can
  // scope a run (one section, one module, one file) instead of turning every
  // round loose on the whole target. Scope is declared by the CONFIG and the
  // First Person — never by the proposer (T2).
  //
  // ctx.runDir is ROUND-SCOPED: runs/<runId>/<roundId>/. It must be, and the
  // spar's first real run proved why. Two rounds whose proposers independently
  // mint the same leverId used to land in the SAME directory —
  // runs/<runId>/p<i>-<leverId> — and the later round silently overwrote the
  // earlier round's proposal_canon.json, destroying an audit trail a verdict
  // still claimed. A win an auditor cannot reproduce is not a win (GR-4). With
  // the round in the path, every (round, proposal) scratch dir is unique, and
  // no config prompt needs to change since they all build from ctx.runDir.
  const ctxFor = (roundId) => ({ root, repo, runId, roundId, runDir: `${runRoot}/${roundId}`, runRoot, config, args: runArgs })

  // Per-seat model/effort. A measure that counts words and a Gap that must
  // hash and draw are not the same job; paying frontier prices for both is how
  // a round dies of its own weight. Defaults to the caller's model.
  const seatOpts = (seat) => (config.seatOpts && config.seatOpts[seat]) || {}

  const rounds = []
  const tally = { VALIDATED: 0, MIRAGE: 0, BLOCKED: 0 }
  let confirmed = []
  let dry = 0
  let round = 0
  let aborted = null   // set when a round dies of infrastructure, not of ideas

  while (dry < config.stop.dryRounds && round < config.stop.maxRounds) {
    round += 1
    const roundId = `${runId}.${round}`
    const ctx = ctxFor(roundId)   // round-scoped scratch: runs/<runId>/<roundId>/

    // ---- Measure — numbers only, no advocacy ----
    phase('Measure')
    log(`round ${roundId} opens — measure syncs the frontier`)
    const measure = await agent(`${BOOT('measure.md')}\n${config.prompts.measure(ctx)}`,
      { label: `measure:${roundId}`, phase: 'Measure', schema: config.schemas.measure, ...seatOpts('measure') })

    // ---- Propose — soulbae 🧙, parallel lenses, blind to each other ----
    phase('Propose')
    const proposalSets = await parallel(config.finders.map(f => () => agent(
      `${BOOT('soulbae-propose.md')}\nHELD-APART RULE (T2/GR-4, binding): ${config.heldApartRule}\n${config.prompts.propose(f, measure, ctx)}`,
      { label: `propose:${f.lens}`, phase: 'Propose', schema: config.schemas.proposal, ...seatOpts('propose') })))
    const proposals = proposalSets.filter(Boolean).flatMap(s => s.proposals || [])
    log(`${proposals.length} proposal(s) on the table: ${proposals.map(p => p.leverId).join(', ') || 'none'}`)

    let closed = []
    let critic = null
    // Code-derive each proposal's seed + draw BEFORE the Gap seat runs (SALTED
    // mode). The proposer has already returned (Propose closed above), and the
    // salt secret is the run's, unseen by any seat — so this is after-commit and
    // grind-proof. In LEGACY mode every entry is null and the Gap computes its
    // own seed as before. This is also the retry-ledger source: every committed
    // proposal's hash, recorded (GR-4).
    const gateCfg = config.gate || null
    const saltSecret = runArgs.saltSecret || null
    const sourceHash = runArgs.sourceHash || null
    const derived = proposals.map(p => deriveHoldApart(p, { gate: gateCfg, saltSecret, sourceHash }))
    const proposalsLog = proposals.map((p, i) => ({ leverId: p.leverId, roundId, hProposal: derived[i]?.hProposal || null, seedHex: derived[i]?.seedHex || null, salted: !!derived[i] }))
    if (proposals.length > 0) {
      // ---- per proposal: Hold-apart (the Gap ⿻) then Assay (soulbis ⚔️), no barrier ----
      closed = (await pipeline(
        proposals,
        (p, _item, i) => agent(
          `${BOOT('gap-hold-apart.md')}\n${config.prompts.holdApart(p, i, ctx, derived[i])}`,
          { label: `gap:${p.leverId}`, phase: 'Hold-apart', schema: config.schemas.gap, ...seatOpts('holdApart') }),
        (gap, p, i) => gap ? agent(
          `${BOOT('soulbis-assay.md')}\n${config.prompts.assay(p, gap, i, ctx)}`,
          { label: `assay:${p.leverId}`, phase: 'Assay', schema: config.schemas.verdict, ...seatOpts('assay') }) : null,
      )).filter(Boolean)
      for (const v of closed) tally[v.status] = (tally[v.status] || 0) + 1
      log(`assay closed: ${closed.length}/${proposals.length} — ${JSON.stringify(tally)}`)

      // ---- Critic — the only barrier: classifies the WHOLE round ----
      phase('Critic')
      critic = await agent(
        `${BOOT('critic.md')}\n${config.prompts.critic(proposals, closed, ctx)}`,
        { label: `critic:${roundId}`, phase: 'Critic', schema: config.schemas.critic, ...seatOpts('critic') })
    }

    // ---- Chronicle — draft only; the keystone reviews and files ----
    phase('Chronicle')
    const roundData = { roundId, measure, proposals, verdicts: closed, critic, holdApart: derived, proposalsLog }
    const chronicle = await agent(
      `${BOOT('chronicle.md')}\n${config.prompts.chronicle(roundData, ctx)}`,
      { label: `chronicle:${roundId}`, phase: 'Chronicle', ...seatOpts('chronicle') })

    // ---- failure accounting (GR-5): a seat that DIED is not a seat that
    // found nothing. A round that lost agents to infrastructure carries no
    // evidence either way, and must never be counted as a dry round —
    // otherwise stop.dryRounds silently converts an outage into "the search
    // is exhausted", and the run reports a clean stop over a pile of corpses.
    const failures = []
    if (measure == null) failures.push('measure')
    const deadFinders = proposalSets.filter(s => s == null).length
    if (deadFinders) failures.push(`propose×${deadFinders}/${config.finders.length}`)
    if (proposals.length > 0) {
      const deadClosings = proposals.length - closed.length
      if (deadClosings) failures.push(`hold-apart|assay×${deadClosings}/${proposals.length}`)
      if (critic == null) failures.push('critic')
    }
    if (chronicle == null) failures.push('chronicle')

    // ---- dry-round accounting: only validated AND structural resets ----
    const validated = closed.filter(v => config.isValidated(v, measure))
    const structural = critic ? validated.filter(v => config.isStructural(critic, v.leverId)) : []

    if (failures.length > 0) {
      aborted = { roundId, failures }
      rounds.push({ ...roundData, roundStatus: 'FAILED', failures, chronicleDraft: chronicle ? String(chronicle).slice(0, 600) : null, validated: [] })
      log(`ROUND ${roundId} FAILED — dead seats: ${failures.join(', ')}. NOT counted as a dry round. Stopping: an incomplete round proves nothing (GR-5).`)
      break
    }

    if (structural.length > 0) { dry = 0; confirmed = confirmed.concat(structural) } else { dry += 1 }
    rounds.push({ ...roundData, roundStatus: 'COMPLETE', chronicleDraft: String(chronicle).slice(0, 600), validated: validated.map(v => v.leverId) })
    log(`round ${roundId} closes — ${structural.length} structural win(s), dry=${dry}/${config.stop.dryRounds}`)
  }

  // Φ_inference (D4b): record the model pair so a verdict produced by one model
  // in two hats is legible as such forever. 0 = same model (the separation term
  // is zero by the PVM); 1 = a genuinely distinct prover.
  const proposerModel = seatOpts('propose').model || '(caller default)'
  const proverModel = seatOpts('assay').model || '(caller default)'
  const phiInference = proposerModel === proverModel ? 0 : 1

  const status = aborted ? 'INCOMPLETE' : 'COMPLETE'
  return {
    name: config.name, runId, status, rounds: rounds.length, tally, confirmed,
    models: { proposer: proposerModel, prover: proverModel }, phiInference,
    best: confirmed.length ? confirmed[confirmed.length - 1] : null,
    detail: rounds,
    ...(aborted ? { aborted } : {}),
    keystoneTodo: aborted
      ? `RUN INCOMPLETE — round ${aborted.roundId} lost seats to infrastructure (${aborted.failures.join(', ')}), not to exhausted ideas. FOLD NOTHING: no gate ran on the dead seats, so no verdict here is evidence (GR-5). Re-run the round; the surviving proposals are candidates, not results. Do not move frontier.json.`
      : 'fold VALIDATED levers (frontier.json first, prose second — GR-1); file killedLeverDrafts (GR-6); review + file the chronicle drafts (GR-7); node engine/conform.mjs green before and after (G0); door items listed for the First Person, never opened (G4/T6)',
  }
}

// harness.config.mjs — hh_workshop: the Hitchhikers Workshop harness.
//
// Domain: the babblefish recursion (sci-fi narrative → poem → white paper →
// recurse) run as a facilitated course around a shared air-gapped local mage.
// The harness guards TRANSLATION FIDELITY: the domain's mirage is a beautiful
// rendering that no longer carries the mechanism. The access ladder
// (workshop/UNDERSTANDING_KEY.md) is deliberately NOT this harness — it is an
// enumerable auditor plus a human door.
//
// Seats are PURE-DATA (a divergence from the template, named in VENDOR.md):
// every seat returns JSON matching its schema and never runs shell commands —
// an Ollama chat endpoint cannot sha256sum. The DRIVER (driver/run_round.mjs)
// persists proposal_canon.json / gap.json / verdict.json and computes all
// hashes code-side via engine deriveHoldApart (SALTED mode), which holds T2
// harder: the seat physically cannot see the salt.
//
// Contract: SEAT_CONTRACT.md (upstream). Constitution: TRUSTS.md (vendored
// verbatim). Gate definition first — see heldApartRule.

const config = {
  name: 'hh_workshop',

  objective: {
    metric:
      'translation-debt — the count of (claim, form) pairs not yet carried ' +
      'across the babblefish recursion; counting rule: node tools/measure_debt.mjs ' +
      '(debt = 3·N − |union of declared (claim,form) pairs in counted carry.json ' +
      'files|). Lower is better; 0 = every claim carried in every tongue.',
    gate:
      'the babblefish gate — a CENSUS over the frozen claim register ' +
      'canon/UNDERSTANDING.md (N=31). The probe form is drawn Fiat-Shamir from ' +
      'the committed triptych: parseInt(seedHex.slice(0,8),16) % 3 → 0=narrative, ' +
      '1=poem, 2=paper. A blind assayer who has NEVER seen the canon receives the ' +
      'probe form text alone and must recover every claim that form declares in ' +
      'its carry.json; the keystone compares recovered statements against the ' +
      'register. Any declared claim the assayer cannot recover = zero (T5: the ' +
      'gate is a factor in a product).',
    hardConstraint:
      '(a) NO CANON DRIFT — a triptych may not assert anything the register ' +
      'contradicts; new understanding lands only as keystone-accepted numbered ' +
      'claims, additive-only (GR-3). (b) CONSENT-FIRST — no participant ' +
      'expression enters corpus/ or any export without a recorded line in ' +
      'corpus/CONSENT_LEDGER.md; a violated consent makes the result not exist, ' +
      'whatever the debt says (T4 as a hard constraint).',
    canary:
      'canon/seed-triptych/ — three renderings authored WITH the register in the ' +
      'same session (both distilled from the 2026-06-28 LAN-ceremony chronicle), ' +
      'so every claim a form declares in carry.json is recoverable from that ' +
      'form by construction. Probe any tongue: the declared set survives. ' +
      'Without it, a round of zeros could not tell a bad triptych from an ' +
      'impossible gate.',
  },

  door: 'first-person', // T6 — the literal; conform.mjs checks it

  // Census, forced and honest: N=31 << censusThreshold, so every claim is
  // probed every round. The Fiat-Shamir randomness the proposer cannot tune
  // gates WHICH FORM is interrogated — only a triptych that carries its
  // declarations in all three tongues survives, which is the babblefish thesis
  // made mechanical. The census gates the claims; the draw gates the form.
  gate: { N: 31, count: 31, mode: 'census', censusThreshold: 200 },

  heldApartRule:
    'You are BLIND to verification witnesses (T2/GR-4). The witnesses are the ' +
    'numbered claims of canon/UNDERSTANDING.md interrogated through ONE probe ' +
    'form (narrative | poem | paper) selected by hashing your committed ' +
    'proposal with a run salt you never see — you cannot know which of your ' +
    'three tongues will be interrogated, so do not tune one. Do not suggest ' +
    'probe forms, claim orderings, questions, or assayers.',

  keystoneOnlyWrites: ['frontier.json', 'claims_register.md', 'manifest.yaml', 'canon/UNDERSTANDING.md'],

  finders: [
    {
      lens: 'story-forward',
      hint:
        'enter at the narrative: where does the myth fail to carry the ' +
        'mechanism? Find (claim, form) pairs the story could carry but does ' +
        'not, and propose the rendering move that would carry them without ' +
        'breaking the tale.',
    },
    {
      lens: 'spec-forward',
      hint:
        'enter at the white paper: where does the mechanism fail to carry the ' +
        'myth? Find claims stated formally that the poem or narrative drops, ' +
        'and propose the translation move that would carry them without ' +
        'canon drift.',
    },
  ],

  prompts: {
    // The DRIVER measures (node tools/measure_debt.mjs) and injects the result
    // as ctx.args.measured; the seat restates it as schema data and flags
    // staleness against frontier.json. Numbers only, no advocacy.
    measure: (ctx) =>
      `Seat MEASURE. The counting rule (tools/measure_debt.mjs) has already run; its output:
${JSON.stringify(ctx.args.measured || null)}
Compare metric (the "debt" field) against the frontier you read at boot: stale=true if frontier.json best.metric differs from this measured debt. leverCosts: price the lever families 'extend-a-tongue' (add declared claims to one form of an existing triptych), 'new-triptych' (a fresh three-form rendering), 'revise-for-fidelity' (repair a form that failed its probe). cost = rough effort, ceiling = how much debt that family could remove. Return JSON only.`,

    propose: (finder, measure, ctx) =>
      `Seat PROPOSE — soulbae 🧙 (bnot), lens = ${finder.lens}: ${finder.hint}
Frontier context: ${JSON.stringify(measure)}.
Triptych under work (if any): ${JSON.stringify(ctx.args.triptych ? { title: ctx.args.triptych.title, carry: ctx.args.triptych.carry } : null)}.
You read notes/KILLED_LEVERS.md at boot; never re-propose a K-id without new cited evidence.
Propose exactly 1 lever through YOUR lens: a concrete translation move that reduces translation-debt. diffPlan must name the triptych directory, the form file(s) to change, and the exact (claim, form) pairs the move would add to carry.json. expectedMetric = the debt after your move if validated. Plan only — never implement, never render the text yourself. Return JSON only.`,

    // SALTED mode: the engine has already code-derived this proposal's seed,
    // salt, and census draw (4th argument). The seat narrates and returns the
    // gap AS DATA; the driver persists proposal_canon.json and gap.json and
    // the auditor replays the same engine function (verify_run.mjs).
    holdApart: (proposal, i, ctx, derived) =>
      `Seat HOLD-APART — the Gap ⿻ (xor). The engine has code-derived the hold-apart for this committed proposal (you never see the salt secret):
${JSON.stringify(derived ? { hProposal: derived.hProposal, seedHex: derived.seedHex, mode: derived.mode, N: derived.N } : null)}
Probe-form rule (state it in your transcript): parseInt(seedHex.slice(0,8),16) % 3 → 0=narrative, 1=poem, 2=paper. Return JSON: seedHex = the derived seedHex verbatim; draw = "census C1..C${ctx.config.gate.N} through probe form <name>"; transcript = one paragraph a third party can re-derive from — canonical JSON of the proposal, sha256 → hProposal, salted seed, census over N=${ctx.config.gate.N}, probe-form arithmetic shown. Never accept proposer-suggested witnesses (T2). Return JSON only.`,

    // The assayer is BLIND to the canon: it receives the PROBE FORM's text and
    // that form's declared claim IDS (not their statements) — the prompt
    // builder slices out the one probed tongue, so the seat never sees the
    // other two forms either. It must state, for each declared id, the claim
    // it recovers from the text — the keystone compares those statements
    // against the register it alone holds.
    assay: (proposal, gap, i, ctx) => {
      const t = ctx.args && ctx.args.triptych
      let probeBlock = { note: 'dry run — no triptych mounted; grade the proposal plan structurally instead (BLOCKED unless the plan itself is assayable)' }
      if (t && gap && gap.seedHex) {
        const FORMS = ['narrative', 'poem', 'paper']
        const probe = FORMS[parseInt(gap.seedHex.slice(0, 8), 16) % 3]
        probeBlock = {
          probeForm: probe,
          declaredClaims: (t.carry || {})[probe] || [],
          text: (t.texts || {})[probe] || '(missing form text)',
        }
      }
      return `Seat ASSAY — soulbis ⚔️ (neg), the prover. You are BLIND to canon/UNDERSTANDING.md — do not open it; your boot list does not include it (T3).
Proposal under assay: ${JSON.stringify(proposal)}
Gap: ${JSON.stringify({ seedHex: gap.seedHex, draw: gap.draw })}
Probe-form arithmetic: parseInt(seedHex.slice(0,8),16) % 3 → 0=narrative, 1=poem, 2=paper.
Probe materials (driver-mounted; canon and the other two tongues withheld): ${JSON.stringify(probeBlock)}
For EACH claim id the probe form declares: recover from the probe text alone a one-sentence statement of that claim. If any declared id yields nothing recoverable, the gate is ZERO (T5). status: VALIDATED only if every declared id recovers AND the hard constraint holds (no assertion contradicting the recovered set's own logic; consent line present for any corpus material) AND expectedMetric beats the frontier. Otherwise MIRAGE (name the failing check: which claim id failed on which form) or BLOCKED (name what is missing). gateResult = "<recovered>/<declared>". metric = the proposal's expectedMetric if validated, else the current debt. evidence = your per-claim recovered statements, numbered. Return JSON only.`
    },

    critic: (proposals, verdicts, ctx) =>
      `Seat CRITIC. Proposals: ${JSON.stringify(proposals)}
Verdicts: ${JSON.stringify(verdicts)}
Classify each closed lever structural / probe-limited / noise / mis-gated. Red-team the PROPOSER's rationale, never the prover's verdict: a MIRAGE on the poem tongue usually means the poem was tuned for beauty over carriage — say so plainly. Draft KILLED_LEVERS entries for structural kills. Name exactly ONE next lead (the single most debt-reducing translation move left open). Return JSON only.`,

    chronicle: (round, ctx) =>
      `Seat CHRONICLE. Draft the round chronicle following ${ctx.root}/templates/chronicle.md: verdict-first, reversals at win-prominence, handoff block ending in the critic's nextLead. Round data: ${JSON.stringify(round)}. Return ONLY the chronicle markdown body as text (the driver writes it to ${ctx.runDir}/CHRONICLE_DRAFT.md).`,
  },

  schemas: {
    measure: {
      type: 'object', required: ['metric', 'stale', 'leverCosts'],
      properties: {
        metric: { type: 'number' },
        stale: { type: 'boolean' },
        leverCosts: { type: 'array', items: { type: 'object', required: ['lever', 'cost', 'ceiling'], properties: { lever: { type: 'string' }, cost: { type: 'string' }, ceiling: { type: 'string' } } } },
        notes: { type: 'string' },
      },
    },
    proposal: {
      type: 'object', required: ['proposals'],
      properties: {
        proposals: {
          type: 'array', minItems: 1,
          items: {
            type: 'object',
            required: ['leverId', 'title', 'lens', 'rationale', 'expectedMetric', 'hardConstraintNote', 'diffPlan'],
            properties: {
              leverId: { type: 'string' }, title: { type: 'string' }, lens: { type: 'string' },
              rationale: { type: 'string' }, expectedMetric: { type: 'number' },
              hardConstraintNote: { type: 'string' }, diffPlan: { type: 'string' },
              killedLeverCitations: { type: 'array', items: { type: 'string' } },
            },
          },
        },
      },
    },
    gap: {
      type: 'object', required: ['seedHex', 'draw', 'transcript'],
      properties: {
        seedHex: { type: 'string' },
        draw: { type: 'string', description: 'the witnesses drawn, as data (census + probe form)' },
        transcript: { type: 'string', description: 'serialization + hash + draw rule, third-party re-derivable' },
      },
    },
    verdict: {
      // gateResult and metric are REQUIRED here (a divergence from the
      // template): with a schema-forced local model, an optional field is a
      // field the model may omit — and verify_run refuses a VALIDATED with no
      // recorded pass ratio. Required-ness is what makes the driver's format
      // enforcement produce it (learned from run live1, 2026-07-17).
      type: 'object', required: ['leverId', 'status', 'gateResult', 'metric', 'evidence'],
      properties: {
        leverId: { type: 'string' },
        status: { type: 'string', enum: ['VALIDATED', 'MIRAGE', 'BLOCKED'] },
        metric: { type: 'number' }, gateResult: { type: 'string' },
        failingCheck: { type: 'string' }, evidence: { type: 'string' }, scratchDir: { type: 'string' },
      },
    },
    critic: {
      type: 'object', required: ['classifications', 'nextLead'],
      properties: {
        classifications: { type: 'array', items: { type: 'object', required: ['leverId', 'class', 'why'], properties: { leverId: { type: 'string' }, class: { type: 'string', enum: ['structural', 'probe-limited', 'noise', 'mis-gated'] }, why: { type: 'string' } } } },
        nextLead: { type: 'string' },
        killedLeverDrafts: { type: 'array', items: { type: 'string' } },
      },
    },
  },

  stop: { dryRounds: 2, maxRounds: 5 },

  isValidated: (v) => v.status === 'VALIDATED',
  isStructural: (critic, leverId) =>
    (critic.classifications || []).some(c => c.leverId === leverId && c.class === 'structural'),

  // instance checks conform.mjs runs on frontier.json: the debt is a count.
  conformChecks: [
    (f) => {
      const errs = []
      if (!Number.isInteger(f.baseline?.metric) || f.baseline.metric < 0) errs.push('baseline.metric must be a non-negative integer (a count of (claim,form) pairs)')
      if (!Number.isInteger(f.best?.metric) || f.best.metric < 0) errs.push('best.metric must be a non-negative integer')
      return errs
    },
  ],
}

// ---- run (Workflow globals: agent, parallel, pipeline, phase, log, args) ----
const A = (typeof args === 'string') ? JSON.parse(args) : (args || {})
if (!A.repo) throw new Error('args.repo required (absolute path to this harness instance); args.root = the skeleton clone holding GROUND_RULES.md/TRUSTS.md/seats/, if the instance does not carry its own copies')
return await runHarness(config, { agent, parallel, pipeline, phase, log }, A)
